-- public-profile: generated by `npm run guide:content` from content/guide/public-profile.ts. Edit the source, not this file.
update public.guide_steps set lesson = $json${
  "minutes": 12,
  "outcome": "Вы собираете результат маршрута в одном месте проекта: цикл задачи, образец PR, «Было / Стало» и настройки агента — опору для себя и команды на следующие задачи.",
  "blocks": [
    {
      "type": "text",
      "text": "Маршрут вы проходили по шагам, но польза — в системе: правилах, проверках и привычках, которые остаются в проекте. Этот шаг собирает их в одном месте, чтобы следующая задача начиналась не с нуля."
    },
    {
      "type": "heading",
      "text": "Что собрать"
    },
    {
      "type": "list",
      "items": [
        "**Цикл задачи**: критерий, план, шаги с проверками, ревью, PR — как он сложился у вас.",
        "**Образец**: PR из шага ★.1 и «Было / Стало» из шага ★.2.",
        "**Настройки проекта**: CLAUDE.md, правила разрешений, хуки, свои команды и субагенты (этапы 2, 5 и 6).",
        "**Что дальше**: какие задачи вы теперь отдадите агенту целиком."
      ]
    },
    {
      "type": "code",
      "file": "docs/agents.md",
      "code": "# Как мы работаем с агентами\n\n## Цикл задачи\nКритерий → план → шаги с проверками → ревью в чистом контексте → PR\n\n## Образец\n- [Экспорт заказов в CSV](ссылка на PR)\n- Было / Стало: [сравнение](before-after.md)\n\n## Настройки\n- Правила проекта: [CLAUDE.md](../CLAUDE.md)\n- Разрешения и хуки: `.claude/settings.json`\n- Команды и субагенты: `.claude/skills/`, `.claude/agents/`\n\n## Дальше\n- [Задача, которую отдам агенту целиком]",
      "caption": "Файл для вас и команды. Показывать ли его кому-то ещё — решать вам."
    },
    {
      "type": "compare",
      "before": {
        "label": "Разовая удача",
        "text": "С экспортом в CSV агент справился отлично.",
        "note": "Через месяц не вспомнить, что сработало и почему."
      },
      "after": {
        "label": "Система",
        "text": "Цикл, образец PR и настройки записаны в docs/agents.md.",
        "note": "Следующая задача начинается с готового процесса."
      }
    },
    {
      "type": "callout",
      "tone": "trap",
      "title": "Без секретов в заметках",
      "text": "Ключи, внутренние адреса и данные клиентов не место в репозитории — даже в документе для своих. Ссылайтесь на настройки, а не копируйте их значения (шаг 4.4)."
    },
    {
      "type": "callout",
      "tone": "tip",
      "title": "Процесс важнее модели",
      "text": "Модели и инструменты сменятся. Критерии, ревью и автоматические проверки останутся — их и держите в порядке, пересматривая файл, когда меняется проект."
    },
    {
      "type": "text",
      "text": "На этом маршрут пройден. Дальше — та же цепочка на каждой задаче: с каждым разом она занимает меньше внимания и даёт больше результата."
    }
  ],
  "practice": {
    "task": "Соберите в `docs/agents.md` своего проекта цикл задачи, ссылки на PR из шага ★.1 и сравнение из ★.2, а также на настройки агента. Запишите следующую задачу, которую отдадите агенту целиком.",
    "done": [
      "в одном файле — цикл задачи, образец и ссылки на настройки проекта;",
      "в файле нет ключей, внутренних адресов и чужих данных;",
      "записана следующая задача для агента."
    ]
  }
}$json$::jsonb where step_id = 'public-profile';
delete from private.guide_checks where step_id = 'public-profile';

